<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'&&PHP_SAPI!=='phpdbg'){http_response_code(404);exit;}
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/config/backup_step18.php';
try{$pdo=business_db();backup_step18_ensure($pdo);$ctx=backup_step18_context($pdo);$orgId=(int)$ctx['organization_id'];$policy=backup_step18_policy($pdo,$orgId);if(!(int)$policy['is_enabled']){fwrite(STDOUT,"STEP 18 scheduled backup policy is disabled.\n");exit(0);}$pass=(string)(getenv('HWC_BACKUP_PASSPHRASE')?:'');backup_step18_assert_passphrase($pass);$type=backup_step18_scheduled_type();$created=backup_step18_create_backup($pdo,$pass,$type,'Scheduled CLI backup',null);$verify=backup_step18_verify_record($pdo,(int)$created['id'],$pass,null);if($verify['status']!=='verified')throw new RuntimeException('Scheduled backup verification failed: '.$verify['detail']);$clean=backup_step18_cleanup_expired($pdo,$orgId,null);$pdo->prepare("UPDATE backup_policies SET last_success_at=NOW(),last_failure_at=NULL,last_failure_message=NULL WHERE organization_id=? AND policy_code='PRIMARY'")->execute([$orgId]);fwrite(STDOUT,'Backup '.$created['backup_code'].' verified. '.$clean." expired record(s) cleaned.\n");exit(0);}catch(Throwable $e){try{if(isset($pdo,$orgId))$pdo->prepare("UPDATE backup_policies SET last_failure_at=NOW(),last_failure_message=? WHERE organization_id=? AND policy_code='PRIMARY'")->execute([substr($e->getMessage(),0,4000),$orgId]);}catch(Throwable $ignore){}fwrite(STDERR,'STEP 18 scheduled backup failed: '.$e->getMessage()."\n");exit(1);}